// Internal source holder for the uniffi-generated Kotlin bindings and the
// per-ABI Rust cdylibs. The single published Android artifact is `:maps-sdk`,
// whose source sets compile these sources into one AAR; this module is kept
// so `scripts/build-android.sh` has one place to generate into and so the
// bindings can be assembled and inspected on their own.
//
// Regenerate the sources and jniLibs with `scripts/build-android.sh`; the
// committed artifacts are inputs to this build, not generated by it.
plugins {
    id("com.android.library") version "9.0.0"
    // AGP 9.0 embeds Kotlin support itself, which is why no
    // `org.jetbrains.kotlin.android` plugin is applied here.
}

// The module carries no publication identity of its own: `:maps-sdk`
// publishes the one artifact. Its namespace is the released Kotlin package's
// `.nativestyle` child.
group = "com.angoratek"
version = "0.1.0"

android {
    namespace = "com.rusticmaps.sdk.nativestyle"
    compileSdk = 36

    defaultConfig {
        // The NDK linker binaries used by `scripts/build-android.sh` target
        // API level 24; JNA (and thus uniffi's Kotlin runtime) requires 21.
        minSdk = 24
        // The `Java_com_rusticmaps_sdk_NativeWindowBridge_*` symbols in
        // `librustic_maps.so` are bound to an exact Kotlin class name, so
        // a consuming app's R8 pass must not rename or strip that class.
        consumerProguardFiles("consumer-rules.pro")
    }

    // Package-level notices (docs/Release.md (The artifacts)): the dual
    // license files and the third-party notices ride in the AAR's assets
    // tree, staged there by scripts/build-android.sh before assembleRelease.
    sourceSets.getByName("main").assets.srcDir("build/generated/sdk-licenses")

    // AGP 9.0's built-in Kotlin support is configured through the `kotlin`
    // extension; the historical `android.kotlinOptions` block is gone.
    compileOptions {
        sourceCompatibility = JavaVersion.VERSION_17
        targetCompatibility = JavaVersion.VERSION_17
    }
    // Lint gates the release build. The generated bindings carry style-only
    // diagnostics of their own; an actual lint error still fails the build.
    lint {
        abortOnError = true
    }
}

kotlin {
    compilerOptions {
        jvmTarget.set(org.jetbrains.kotlin.gradle.dsl.JvmTarget.JVM_17)
    }
}

dependencies {
    // JNA drives the FFI calls of the generated bindings; the AAR classifier
    // is required because the plain JAR's native stubs do not resolve on
    // Android.
    implementation("net.java.dev.jna:jna:5.18.1@aar")
    // Uniffi lowers per-member `[Async]` UDL methods to `suspend fun` backed
    // by `CancellableContinuation`.
    implementation("org.jetbrains.kotlinx:kotlinx-coroutines-core:1.10.2")
}
